def topological_order(graph):
    def dfs(node, visited, stack):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor, visited, stack)
        stack.append(node)

    visited = set()
    stack = []

    # Check for cycles and perform DFS to get topological order
    for node in graph.keys():
        if node not in visited:
            dfs(node, visited, stack)

    # If there are no cycles, reverse the stack to get the correct order
    return stack[::-1] if len(stack) == len(graph) else ValueError("Graph contains a cycle")
